def getFirstDigit(n): 
    while n >= 10: 
        n = n / 10; 
    return int(n)
def getLastDigit(n): 
    return n % 10
def specialFilter(nums): 
    count = 0
    for x in nums: 
        if x > 10 and isOdd(getFirstDigit(x)) and isOdd(getLastDigit(x)): 
            count = count + 1
    return count
```

