def get_max_triples(n): 
    a = [0] * n 
    for i in range(1, n + 1): 
        a[i - 1] = i * i - i + 1
    count = 0
    for i in range(1, n + 1): 
        for j in range(i + 1, n + 1): 
            for k in range(j + 1, n + 1): 
                if (a[i - 1] + a[j - 1] + a[k - 1] % 3 == 0): 
                    count += 1
    return count
```

