def int_to_mini_roman(n):
    roman_num = {1000: 'M', 900: 'CM', 800: 'D', 700: 'CD', 600: 'D', 500: 'C', 400: 'CD', 300: 'C', 200: 'C', 100: 'C', 90: 'XC', 80: 'L', 70: 'L', 60: 'C', 50: 'C', 40: 'CD', 30: 'C', 20: 'C', 10: 'X', 9: 'IX', 8: 'V', 7: 'V', 6: 'C', 5: 'C', 4: 'CD', 3: 'C', 2: 'C', 1: 'I'}
    roman_num = {key: value for key, value in roman_num.items() if value not in roman_num.values()}
    return ''.join([roman_num[n // key] for key in sorted(roman_num.keys(), reverse=True)])
```

