def solve(s):
    letters = []
    digits = []
    for i in s:
        if i.isalpha():
            letters.append(i)
        else:
            digits.append(i)
    for i in range(len(letters)):
        letters[i] = letters[i].upper() if i % 2 == 0 else letters[i].lower()
    return (digits + letters)
```

